-- Canonical lesson packages generated by the Fast and Full workspaces.
-- Source files are intentionally not persisted in this first slice; only their
-- names and sizes are kept in the canonical input for traceability.
create table if not exists public.lessons (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  plan_code text not null check (plan_code in ('fast', 'full')),
  input jsonb not null,
  content jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists lessons_workspace_created_at_idx
  on public.lessons (workspace_id, created_at desc);

alter table public.lessons enable row level security;

drop policy if exists "owners can read their lessons" on public.lessons;
create policy "owners can read their lessons"
  on public.lessons
  for select
  to authenticated
  using (
    exists (
      select 1
        from public.workspaces
       where workspaces.id = lessons.workspace_id
         and workspaces.owner_id = (select auth.uid())
    )
  );

drop policy if exists "owners can create their lessons" on public.lessons;
create policy "owners can create their lessons"
  on public.lessons
  for insert
  to authenticated
  with check (
    exists (
      select 1
        from public.workspaces
       where workspaces.id = lessons.workspace_id
         and workspaces.owner_id = (select auth.uid())
    )
    and plan_code in ('fast', 'full')
  );

drop policy if exists "owners can update their lessons" on public.lessons;
create policy "owners can update their lessons"
  on public.lessons
  for update
  to authenticated
  using (
    exists (
      select 1
        from public.workspaces
       where workspaces.id = lessons.workspace_id
         and workspaces.owner_id = (select auth.uid())
    )
  )
  with check (
    exists (
      select 1
        from public.workspaces
       where workspaces.id = lessons.workspace_id
         and workspaces.owner_id = (select auth.uid())
    )
  );

grant select, insert, update on public.lessons to authenticated;

